const localNuc=['127.0.0.1','localhost','::1'].includes(location.hostname)&&!window.DartsAndroid;
const localOwner=localNuc||!!window.DartsAndroid?.isLocalMode?.();
const CENTRAL_SERVER='https://180-hitters-online.180-hitters-online.workers.dev';
const hostOpen=document.createElement('button');hostOpen.id='online-host-open';hostOpen.type='button';hostOpen.textContent='Dartbaan aanmaken';
const joinOpen=document.createElement('button');joinOpen.id='online-join-open';joinOpen.type='button';joinOpen.textContent='Deelnemen aan online dartbaan';document.getElementById('top-actions').append(hostOpen,joinOpen);
const newOpen=document.createElement('button');newOpen.id='online-new-open';newOpen.type='button';newOpen.textContent='Nieuwe dartbaan aanmaken';newOpen.hidden=true;document.getElementById('top-actions').append(newOpen);
const dialog=document.createElement('dialog');dialog.id='online-dialog';dialog.className='online-dialog';dialog.innerHTML=`
<h2 id="online-title">Online darten - 4 op een rij</h2><p id="online-intro"></p>
<fieldset id="online-host-section"><legend>Nieuwe dartbaan</legend><label>1. Uw naam<input id="online-host-name" maxlength="24" autocomplete="name"></label><label>2. Aantal spelers<select id="online-capacity"><option>2</option><option>3</option><option>4</option></select></label><label class="online-check"><input id="online-public" type="checkbox" checked> 3. Zichtbaar maken in de openbare lijst</label><p>Na het aanmaken kunt u spelers rechtstreeks via WhatsApp uitnodigen.</p><button id="online-host" class="primary wide">Dartbaan aanmaken</button></fieldset>
<fieldset id="online-join-section"><legend>Vrije dartbaan kiezen</legend><label>Uw naam<input id="online-guest-name" maxlength="24" autocomplete="name"></label><div class="online-lobby-heading"><strong>Beschikbare dartbanen</strong><button id="online-lobby-refresh" type="button">Lijst vernieuwen</button></div><div id="online-lobby" class="online-lobby"><p>Beschikbare dartbanen laden…</p></div><details><summary>Ik heb een uitnodigingslink</summary><label>Plak de uitnodigingslink<input id="online-invite-input" autocomplete="off" placeholder="https://...workers.dev/?dartbaan=ABC123"></label><button id="online-join" class="primary wide">Deelnemen met uitnodiging</button></details></fieldset>
<section id="online-active" hidden><div class="online-active-summary"><span>Dartbaancode</span><strong id="online-code"></strong><span id="online-occupancy"></span></div><button id="online-new" class="primary wide" hidden>Huidige dartbaan verlaten en nieuwe aanmaken</button><div id="online-host-controls"><p>Nodig spelers uit of maak de dartbaan leeg voor een nieuw spel.</p><button id="online-share" class="primary wide">Uitnodiging delen</button><button id="online-copy" class="wide">Uitnodiging kopiëren</button><button id="online-reset" class="wide">Dartbaan leegmaken voor nieuw spel</button></div></section>
<p id="online-status" class="online-dialog-status" role="status"></p><div class="online-actions"><button id="online-leave">Dartbaan verlaten</button><button id="online-close">Sluiten</button></div>`;document.body.append(dialog);
const indicator=document.createElement('div');indicator.id='online-indicator';indicator.hidden=true;document.body.append(indicator);
const starterNotice=document.createElement('section');starterNotice.id='online-starter';starterNotice.className='online-starter';starterNotice.hidden=true;starterNotice.setAttribute('role','dialog');starterNotice.setAttribute('aria-modal','true');starterNotice.innerHTML='<div><span id="online-starter-label">Alle spelers zijn aanwezig</span><h2 id="online-starter-name">Wie begint?</h2><p id="online-starter-detail">Spreek dit samen af en tik de gekozen speler aan.</p><div id="online-starter-options"></div><button id="online-starter-close" class="primary wide" hidden>Spel openen</button></div>';document.body.append(starterNotice);
const $=id=>document.getElementById(id);let session=null,remote=null,syncing=false,socket=null,reconnectTimer=null,dialogMode='host',announcedStarter='';
async function json(url,options={}){const response=await fetch(url,{cache:'no-store',...options});let data={};try{data=await response.json();}catch{}if(!response.ok){const error=Error(data.error||`Verbinding mislukt (${response.status}).`);error.status=response.status;error.data=data;throw error;}return data;}
async function localState(){return json('/api/state');}
async function saveLocal(match){const current=await localState();if(JSON.stringify(current.match?.state)===JSON.stringify(match?.state))return current;return json('/api/state',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision:current.revision,match})});}
async function saveSession(value){session=value;await json('/api/online/local',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(value)});paint();if(session.active&&localOwner)connect();}
function invite(){return session?.active?`${session.base}/?dartbaan=${session.code}`:'';}
function renderDialog(state=null){const active=!!session?.active,host=session?.role===0,switching=dialogMode==='new';$('online-active').hidden=!active;$('online-host-section').hidden=active||dialogMode!=='host';$('online-join-section').hidden=active||dialogMode!=='join';$('online-leave').hidden=!active;$('online-new').hidden=!active||!switching;$('online-host-controls').hidden=!host||switching;$('online-reset').hidden=!host;$('online-share').hidden=!host;$('online-copy').hidden=!host;if(active){const current=state||remote?.match,count=current?.state?.players?.filter(player=>!player.name.startsWith('Wachten op speler')).length||remote?.joined||1,capacity=current?.state?.players?.length||remote?.capacity||'?';$('online-title').textContent=switching?'Nieuwe dartbaan aanmaken':host?'Uw actieve dartbaan':'Verbonden met dartbaan';$('online-intro').textContent=switching?'U bent nog gekoppeld aan een dartbaan. Verlaat deze eerst met de duidelijke knop hieronder.':host?'Beheer hier alleen uw huidige dartbaan.':'U bent verbonden. Sluit dit venster om verder te spelen.';$('online-code').textContent=session.code;$('online-occupancy').textContent=`${count} van ${capacity} spelers aanwezig`;$('online-leave').textContent=host?'Dartbaan sluiten':'Dartbaan verlaten';}else{$('online-title').textContent=dialogMode==='host'?'Dartbaan aanmaken':'Deelnemen aan online dartbaan';$('online-intro').textContent=dialogMode==='host'?'Maak in drie eenvoudige stappen een openbare of besloten dartbaan.':'Vul uw naam in en kies een vrije openbare dartbaan.';}}
function paint(state=null){const active=!!session?.active;hostOpen.textContent=active?'Actieve dartbaan openen':'Dartbaan aanmaken';joinOpen.hidden=active;newOpen.hidden=!active;renderDialog(state);indicator.hidden=!active;document.body.classList.toggle('online-session',active);if(!active){document.body.classList.remove('online-waiting');starterNotice.hidden=true;return;}const current=state||remote?.match,waiting=!session.ready||(current?.state?.active!==undefined&&current.state.active!==session.role);document.body.classList.toggle('online-waiting',waiting);const count=current?.state?.players?.filter(player=>!player.name.startsWith('Wachten op speler')).length,pending=remote?.starterPending;indicator.textContent=`Online dartbaan ${session.code} - speler ${session.role+1}${count?` - ${count}/${current.state.players.length} aanwezig`:''}${pending?' - kies wie begint':!session.ready?' - wacht op spelers':current?.state?.phase==='playing'?(waiting?' - tegenstander aan de beurt':' - jij bent aan de beurt'):''}`;}
function parseInvite(value){const url=new URL(value.trim()),code=(url.searchParams.get('dartbaan')||url.hash.replace(/^#/,'')).toUpperCase();if(url.protocol!=='https:'||!/^[A-Z2-9]{6}$/.test(code))throw Error('Gebruik een geldige uitnodigingslink van 180 Hitters.');return {base:url.origin,code};}
function renderStarter(value){if(!session?.active||value.joined<value.capacity||value.match?.state?.history?.length){starterNotice.hidden=true;return;}if(value.starterPending){announcedStarter='';$('online-starter-label').textContent='Alle spelers zijn aanwezig';$('online-starter-name').textContent='Wie begint?';$('online-starter-detail').textContent='Spreek dit samen af en tik de gekozen speler aan. De eerste keuze wordt voor iedereen vastgezet.';$('online-starter-close').hidden=true;const options=$('online-starter-options');options.replaceChildren();value.match.state.players.forEach((player,index)=>{const button=document.createElement('button');button.type='button';button.textContent=player.name;button.onclick=async()=>{for(const item of options.querySelectorAll('button'))item.disabled=true;try{const selected=await json(`${session.base}/rooms/${session.code}/starter`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key:session.key,starter:index})});await updateRemote(selected);}catch(error){$('online-starter-detail').textContent=error.message;for(const item of options.querySelectorAll('button'))item.disabled=false;}};options.append(button);});starterNotice.hidden=false;return;}if(!Number.isInteger(value.starter))return;const marker=`${value.code}:${value.starter}`;if(announcedStarter===marker)return;announcedStarter=marker;const name=value.match?.state?.players?.[value.starter]?.name||`Speler ${value.starter+1}`;$('online-starter-label').textContent='Startspeler gekozen';$('online-starter-name').textContent=value.starter===session.role?'U mag beginnen!':`${name} begint`;$('online-starter-detail').textContent='De keuze is voor alle spelers vastgezet.';$('online-starter-options').replaceChildren();$('online-starter-close').hidden=false;starterNotice.hidden=false;$('online-status').textContent=`${name} begint de partij.`;}
async function updateRemote(value){if(value.closed){socket=null;remote=null;await saveSession({active:false,ready:false,role:null,code:'',base:'',key:'',remoteRevision:0});$('online-status').textContent=value.error||'De dartbaan is gesloten.';return;}remote=value;const ready=value.joined>=value.capacity&&Number.isInteger(value.starter)&&!value.starterPending;if(session.ready!==ready){session.ready=ready;await json('/api/online/local',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(session)});}renderStarter(value);const local=await localState(),localHistory=local.match?.state?.history?.length??-1,remoteHistory=value.match?.state?.history?.length??-1;if(localHistory===remoteHistory+1&&value.match.state.active===session.role)return push();if(value.revision!==session.remoteRevision||JSON.stringify(local.match?.state)!==JSON.stringify(value.match?.state)){await saveLocal(value.match);session.remoteRevision=value.revision;await json('/api/online/local',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(session)});}paint(value.match);}
async function push(){if(syncing||!session?.active||!localOwner)return;syncing=true;try{if(!remote)remote=await json(`${session.base}/rooms/${session.code}?key=${encodeURIComponent(session.key)}`);const local=await localState(),lh=local.match?.state?.history?.length??-1,rh=remote.match?.state?.history?.length??-1;if(lh===rh+1&&remote.match.state.active===session.role){remote=await json(`${session.base}/rooms/${session.code}/state`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key:session.key,revision:remote.revision,match:local.match})});session.remoteRevision=remote.revision;await json('/api/online/local',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(session)});paint(remote.match);}}catch(error){$('online-status').textContent=error.message;}finally{syncing=false;}}
function connect(){if(!localOwner||!session?.active||socket?.readyState===WebSocket.OPEN||socket?.readyState===WebSocket.CONNECTING)return;clearTimeout(reconnectTimer);const url=`${session.base.replace(/^http/,'ws')}/rooms/${session.code}/socket?key=${encodeURIComponent(session.key)}`;socket=new WebSocket(url);socket.onmessage=event=>{try{void updateRemote(JSON.parse(event.data));}catch{}};socket.onopen=()=>{$('online-status').textContent='Realtime verbonden.';};socket.onclose=()=>{socket=null;if(session?.active)reconnectTimer=setTimeout(connect,1500);};socket.onerror=()=>socket?.close();}
async function joinLane(target,name){if(!name)throw Error('Vul eerst jouw naam in.');remote=await json(`${target.base}/rooms/${target.code}/join`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})});await saveLocal(remote.match);await saveSession({active:true,ready:false,role:remote.role,code:remote.code,base:target.base,key:remote.key,remoteRevision:remote.revision});$('online-status').textContent=remote.starterPending?'Alle spelers zijn aanwezig. Kies samen wie begint.':'Verbonden met de dartbaan.';renderStarter(remote);}
async function loadLobby(){const list=$('online-lobby');list.replaceChildren();const loading=document.createElement('p');loading.textContent='Beschikbare dartbanen laden…';list.append(loading);try{const data=await json(CENTRAL_SERVER+'/lobby');list.replaceChildren();if(!data.rooms?.length){const empty=document.createElement('p');empty.textContent='Er zijn nu geen openbare dartbanen met vrije plaatsen.';list.append(empty);return;}for(const room of data.rooms){const card=document.createElement('div');card.className='online-lobby-room';const details=document.createElement('span');details.textContent=`${room.host} · ${room.joined}/${room.capacity} spelers · code ${room.code}`;const join=document.createElement('button');join.type='button';join.textContent='Deelnemen';join.onclick=async()=>{join.disabled=true;try{await joinLane({base:CENTRAL_SERVER,code:room.code},$('online-guest-name').value.trim());}catch(error){$('online-status').textContent=error.message;if(error.status===409||error.status===404)void loadLobby();}finally{join.disabled=false;}};card.append(details,join);list.append(card);}}catch(error){list.replaceChildren();const failed=document.createElement('p');failed.textContent=`Lijst laden mislukt: ${error.message}`;list.append(failed);}}
async function openOnline(mode){dialogMode=mode;try{session=await json('/api/online/local');paint();if(session.active&&localOwner)connect();}catch{}renderDialog();$('online-status').textContent='';dialog.showModal();if(mode==='join'&&!session?.active)void loadLobby();}
hostOpen.onclick=()=>void openOnline('host');joinOpen.onclick=()=>void openOnline('join');newOpen.onclick=()=>void openOnline('new');$('online-close').onclick=()=>dialog.close();$('online-lobby-refresh').onclick=()=>void loadLobby();
$('online-starter-close').onclick=()=>{starterNotice.hidden=true;};
$('online-host').onclick=async()=>{const name=$('online-host-name').value.trim(),capacity=Number($('online-capacity').value),isPublic=$('online-public').checked;if(!name)return $('online-status').textContent='Vul jouw naam in.';$('online-host').disabled=true;try{const {newMatch}=await import('./engine.js'),names=[name,...Array.from({length:capacity-1},(_,index)=>`Wachten op speler ${index+2}`)],state=newMatch(names,0,'single',1,{game:'fourinarow'}),match={state,undo:[]};await saveLocal(match);remote=await json(CENTRAL_SERVER+'/rooms',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,match,public:isPublic})});await saveLocal(remote.match);await saveSession({active:true,ready:remote.joined>=remote.capacity,role:remote.role,code:remote.code,base:CENTRAL_SERVER,key:remote.key,remoteRevision:remote.revision});$('online-status').textContent=isPublic?'Dartbaan gereed en zichtbaar in de openbare lijst.':'Besloten dartbaan gereed. Deel de uitnodiging.';}catch(error){$('online-status').textContent=error.message;}finally{$('online-host').disabled=false;}};
$('online-join').onclick=async()=>{const button=$('online-join');button.disabled=true;try{await joinLane(parseInvite($('online-invite-input').value),$('online-guest-name').value.trim());}catch(error){$('online-status').textContent=error.message;}finally{button.disabled=false;}};
$('online-share').onclick=async()=>{const url=invite(),text=`Doe mee met mijn online dartbaan in 180 Hitters: ${url}`;try{if(window.DartsAndroid?.shareText){window.DartsAndroid.shareText(text);$('online-status').textContent='Kies WhatsApp of een andere app om de uitnodiging te delen.';}else if(navigator.share){await navigator.share({title:'180 Hitters dartbaan',text,url});}else{await navigator.clipboard.writeText(text);$('online-status').textContent='Uitnodiging gekopieerd. Plak deze in WhatsApp.';}}catch(error){if(error.name!=='AbortError')$('online-status').textContent='Delen is niet gelukt. Gebruik Uitnodiging kopiëren.';}};
$('online-copy').onclick=async()=>{try{await navigator.clipboard.writeText(invite());$('online-status').textContent='Uitnodiging gekopieerd.';}catch{$('online-invite').focus();const selection=getSelection();selection.removeAllRanges();const range=document.createRange();range.selectNodeContents($('online-invite'));selection.addRange(range);$('online-status').textContent='Selecteer en kopieer de uitnodiging.';}};
$('online-reset').onclick=async()=>{if(session?.role!==0||!remote)return;const old={...session},capacity=remote.capacity,name=remote.match?.state?.players?.[0]?.name||'Speler 1',isPublic=remote.public!==false;$('online-reset').disabled=true;try{const {newMatch}=await import('./engine.js'),names=[name,...Array.from({length:capacity-1},(_,index)=>`Wachten op speler ${index+2}`)],state=newMatch(names,0,'single',1,{game:'fourinarow'}),match={state,undo:[]},next=await json(CENTRAL_SERVER+'/rooms',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,match,public:isPublic})});socket?.close();socket=null;await json(`${old.base}/rooms/${old.code}/close`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key:old.key})});remote=next;await saveLocal(next.match);await saveSession({active:true,ready:false,role:0,code:next.code,base:CENTRAL_SERVER,key:next.key,remoteRevision:next.revision});$('online-status').textContent='Nieuwe lege dartbaan gereed. Deel de nieuwe uitnodiging.';}catch(error){$('online-status').textContent=error.message;}finally{$('online-reset').disabled=false;}};
async function leaveCurrent(){const old=session?{...session}:null;if(old?.active)try{await json(`${old.base}/rooms/${old.code}/leave`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key:old.key})});}catch(error){if(error.status!==404)throw error;}socket?.close();socket=null;remote=null;await saveSession({active:false,ready:false,role:null,code:'',base:'',key:'',remoteRevision:0});return old;}
$('online-leave').onclick=async()=>{try{const old=await leaveCurrent();$('online-status').textContent=old?.role===0?'Dartbaan gesloten.':'Dartbaan verlaten.';}catch(error){$('online-status').textContent=error.message;}};
$('online-new').onclick=async()=>{const button=$('online-new');button.disabled=true;try{await leaveCurrent();dialogMode='host';renderDialog();$('online-status').textContent='Vul de gegevens voor uw nieuwe dartbaan in.';}catch(error){$('online-status').textContent=error.message;}finally{button.disabled=false;}};
for(const event of ['match-persisted','match-synchronized'])document.addEventListener(event,()=>void push());
document.addEventListener('click',event=>{if(!session?.active)return;const blocked=document.body.classList.contains('online-waiting')&&event.target.closest('.four-board,.four-controls')||event.target.closest('#undo,#redo,#edit-match,#team-manager,#settings');if(blocked){event.preventDefault();event.stopImmediatePropagation();$('online-status').textContent='Verlaat eerst de online dartbaan om deze functie te gebruiken.';}},true);
async function restore(){try{session=await json('/api/online/local');paint();if(session.active&&localOwner){try{remote=await json(`${session.base}/rooms/${session.code}?key=${encodeURIComponent(session.key)}`);}catch(error){if(error.status===404){await leaveCurrent();$('online-status').textContent='De vorige dartbaan bestond niet meer en is automatisch opgeruimd.';return;}throw error;}await updateRemote(remote);connect();}const incoming=window.DartsAndroid?.takeOnlineInvite?.();if(incoming&&!session.active){$('online-invite-input').value=incoming;await openOnline('join');}}catch(error){if(session?.active){indicator.hidden=false;indicator.textContent='Online dartbaan - verbinding herstellen…';$('online-status').textContent=error.message;setTimeout(restore,2500);}}}restore();
